function initDock() {
  const dock = $('.dock');
  const items = $$('.dock-item', dock);
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const finePointer = matchMedia('(hover: hover) and (pointer: fine)');
  const values = items.map(() => ({ value: 0, velocity: 0, target: 0 }));
  let frame = 0, previousTime = 0;
  const engagement = { value: 0, velocity: 0, target: 0 };
  function animate(time) {
    const step = Math.min((time - previousTime) / 16.667 || 1, 2);
    previousTime = time;
    let moving = false;
    values.forEach((v, index) => {
      v.velocity = (v.velocity + (v.target - v.value) * .16 * step) * Math.pow(.62, step);
      v.value += v.velocity * step;
      if (Math.abs(v.target - v.value) < .001 && Math.abs(v.velocity) < .001) {
        v.value = v.target; v.velocity = 0;
      } else moving = true;
      items[index].style.setProperty('--proximity', Math.max(0, Math.min(1, v.value)).toFixed(4));
    });
    engagement.velocity = (engagement.velocity + (engagement.target - engagement.value) * .14 * step) * Math.pow(.65, step);
    engagement.value += engagement.velocity * step;
    if (Math.abs(engagement.target - engagement.value) < .001 && Math.abs(engagement.velocity) < .001) {
      engagement.value = engagement.target; engagement.velocity = 0;
    } else moving = true;
    dock.style.setProperty('--engagement', Math.max(0, Math.min(1, engagement.value)).toFixed(4));
    frame = moving ? requestAnimationFrame(animate) : 0;
  }
  function schedule() {
    if (reducedMotion.matches) {
      cancelAnimationFrame(frame); frame = 0; engagement.value = engagement.target; engagement.velocity = 0;
      dock.style.setProperty('--engagement', engagement.target);
      values.forEach((v, index) => { v.value = 0; v.velocity = 0; v.target = 0; items[index].style.setProperty('--proximity', '0'); });
      return;
    }
    if (!frame) { previousTime = 0; frame = requestAnimationFrame(animate); }
  }
  function reset() { engagement.target = 0; values.forEach(v => v.target = 0); schedule(); }
  const hitArea = dock.parentElement;
  hitArea.addEventListener('pointermove', event => {
    if (!finePointer.matches || reducedMotion.matches || event.pointerType === 'touch') return;
    engagement.target = 1;
    items.forEach((item, index) => {
      const rect = item.getBoundingClientRect();
      const distance = Math.abs(event.clientX - rect.left - rect.width / 2);
      values[index].target = distance < 115 ? (1 + Math.cos(Math.PI * distance / 115)) / 2 : 0;
    });
    schedule();
  });
  hitArea.addEventListener('pointerleave', reset);
  dock.addEventListener('focusin', event => {
    if (reducedMotion.matches || !event.target.matches(':focus-visible')) return;
    const focused = items.indexOf(event.target.closest('.dock-item'));
    if (focused < 0) return;
    engagement.target = 1;
    values.forEach((v, index) => v.target = Math.max(0, 1 - Math.abs(index - focused) * .6));
    schedule();
  });
  dock.addEventListener('focusout', reset);
  dock.addEventListener('pointerdown', event => {
    if (event.pointerType === 'touch') { engagement.target = 1; schedule(); }
  });
  if (hitArea.matches(':hover') && finePointer.matches && !reducedMotion.matches) { engagement.target = 1; schedule(); }
  reducedMotion.addEventListener('change', reset);
  disposeDock = () => { cancelAnimationFrame(frame); reducedMotion.removeEventListener('change', reset); };
}
